#include <vector>
#include <string>
using namespace std;

class Solution {
public:
    int numWays(vector<string>& words, string target) {
        long long MOD = 1e9 + 7;
        int L = words[0].size();
        int T = target.size();
        vector<vector<int>> col_count(L, vector<int>(26, 0));
        for (const auto& w : words) {
            for (int j = 0; j < L; ++j) {
                col_count[j][w[j] - 'a']++;
            }
        }
        vector<long long> dp(T + 1, 0);
        dp[0] = 1;
        for (int j = 0; j < L; ++j) {
            for (int i = T; i >= 1; --i) {
                int char_idx = target[i - 1] - 'a';
                long long cnt = col_count[j][char_idx];
                if (cnt > 0) {
                    dp[i] = (dp[i] + dp[i - 1] * cnt) % MOD;
                }
            }
        }
        return dp[T];
    }
};

class Solution {
    public int numWays(String[] words, String target) {
        long MOD = 1000000007L;
        int L = words[0].length();
        int T = target.length();
        int[][] colCount = new int[L][26];
        for (String w : words) {
            for (int j = 0; j < L; ++j) {
                colCount[j][w.charAt(j) - 'a']++;
            }
        }
        long[] dp = new long[T + 1];
        dp[0] = 1;
        for (int j = 0; j < L; ++j) {
            for (int i = T; i >= 1; --i) {
                int charIdx = target.charAt(i - 1) - 'a';
                int cnt = colCount[j][charIdx];
                if (cnt > 0) {
                    dp[i] = (dp[i] + dp[i - 1] * cnt) % MOD;
                }
            }
        }
        return (int)dp[T];
    }
}

