var numWays = function(words, target) {
    const MOD = 1000000007n;
    const L = words[0].length;
    const T = target.length;
    const colCount = Array.from({ length: L }, () => Array(26).fill(0n));
    for (const w of words) {
        for (let j = 0; j < L; ++j) {
            colCount[j][w.charCodeAt(j) - 97]++;
        }
    }
    const dp = Array(T + 1).fill(0n);
    dp[0] = 1n;
    for (let j = 0; j < L; ++j) {
        for (let i = T; i >= 1; --i) {
            const charIdx = target.charCodeAt(i - 1) - 97;
            const cnt = colCount[j][charIdx];
            if (cnt > 0n) {
                dp[i] = (dp[i] + dp[i - 1] * cnt) % MOD;
            }
        }
    }
    return Number(dp[T]);
};
